#!/usr/bin/env python3
"""Generate medium_extra.json for the 4 remaining ISTQB exams (45 Qs each)."""
import json, os

B = "apps/web/question-bank"

def emit(exam, prefix, start, rows, target=100):
    meta = json.load(open(f"{B}/{exam}/medium.json", encoding="utf-8"))
    qs, n = [], start
    for r in rows:
        qs.append({
            "id": f"{prefix}-{n:04d}",
            "difficulty": "medium",
            "type": "MCQ",
            "domain": r[0],
            "question": r[1],
            "options": {"A": r[2], "B": r[3], "C": r[4], "D": r[5]},
            "correct_answer": [r[6]],
            "explanation": r[7],
        })
        n += 1
    out = {
        "exam_name": meta["exam_name"],
        "exam_code": meta["exam_code"],
        "duration_minutes": meta["duration_minutes"],
        "live_exam_question_count": meta["live_exam_question_count"],
        "difficulty_tier": "medium",
        "questions_in_this_file": len(qs),
        "target_for_tier": target,
        "last_updated": "2026",
        "questions": qs,
    }
    path = f"{B}/{exam}/medium_extra.json"
    json.dump(out, open(path, "w", encoding="utf-8"), indent=2, ensure_ascii=False)
    total = len(meta["questions"]) + len(qs)
    print(f"{exam}: wrote {len(qs)} Qs ({qs[0]['id']}..{qs[-1]['id']}) -> medium total {total}")


